// One lead per posting. The board name comes from the item that fetched it.
// `places` is only for Apply hard filters, which removes it before saving.
const now = new Date().toISOString();
const leads = [];

// Ashby states pay as components (Salary, EquityCashValue, Commission, Bonus...).
// Only base salary in USD, per year or per month, counts toward the pay floor.
// Anything else (other currencies, other intervals, no salary) is unknown pay.
const PER_YEAR = { '1 YEAR': 1, '1 MONTH': 12 };
function usdBasePay(comp) {
  if (!comp) return { min: null, max: null };
  const components = (comp.summaryComponents || [])
    .concat((comp.compensationTiers || []).flatMap((t) => t.components || []));
  const salary = components.filter((c) =>
    c.compensationType === 'Salary' && c.currencyCode === 'USD' && PER_YEAR[c.interval] &&
    (typeof c.minValue === 'number' || typeof c.maxValue === 'number'));
  if (!salary.length) return { min: null, max: null };
  const k = (c) => PER_YEAR[c.interval];
  const mins = salary.map((c) => (typeof c.minValue === 'number' ? c.minValue : c.maxValue) * k(c));
  const maxes = salary.map((c) => (typeof c.maxValue === 'number' ? c.maxValue : c.minValue) * k(c));
  return { min: Math.min(...mins), max: Math.max(...maxes) };
}

function place(text, address) {
  const a = (address && address.postalAddress) || {};
  return {
    text: String(text || '').trim(),
    country: String(a.addressCountry || '').trim(),
    region: String(a.addressRegion || '').trim(),
    locality: String(a.addressLocality || '').trim(),
  };
}

$input.all().forEach((item, i) => {
  const jobs = item.json.jobs;
  if (!Array.isArray(jobs)) return; // this board's fetch failed; the other boards still run
  const board = $('Split boards').itemMatching(i).json.board;

  for (const job of jobs) {
    if (job.isListed === false) continue;
    const pay = usdBasePay(job.compensation);
    const places = [place(job.location, job.address)]
      .concat((job.secondaryLocations || []).map((l) => place(l.location, l.address)))
      .filter((p) => p.text || p.country || p.region || p.locality);
    leads.push({
      json: {
        lead_key: 'ashby:' + board + ':' + job.id,
        ats: 'ashby',
        board: board,
        job_id: job.id,
        company: board,
        title: job.title,
        location_text: job.location || '',
        workplace_type: job.workplaceType || '',
        secondary_locations: (job.secondaryLocations || [])
          .map((l) => l.location)
          .filter(Boolean)
          .join('; '),
        pay_text: (job.compensation && job.compensation.compensationTierSummary) || '',
        pay_min: pay.min,
        pay_max: pay.max,
        posting_url: job.jobUrl,
        apply_url: job.applyUrl,
        published_at: job.publishedAt || null,
        last_seen_at: now,
        places: places,
      },
    });
  }
});

return leads;

// One Telegram message per lead. Parse mode is HTML, so escape posting text.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// location_basis comes from Apply hard filters: us_remote, metro or unclear.
function where(lead) {
  const stated = [lead.location_text, lead.workplace_type].filter(Boolean).join(' · ');
  if (lead.location_basis === 'unclear') return 'Location unclear' + (stated ? ' (' + stated + ')' : '');
  if (lead.location_basis === 'us_remote' && !/remote/i.test(stated)) return stated + ' · Remote (US) option';
  return stated || 'Location unclear';
}

return $input.all().map(({ json: lead }) => {
  const lines = [
    '<b>' + esc(lead.title) + '</b>',
    esc(lead.company),
    'Location: ' + esc(where(lead)),
    'Pay: ' + esc(lead.pay_text || 'Pay not listed'),
  ];
  if (lead.published_at) lines.push('Posted: ' + String(lead.published_at).slice(0, 10));

  return {
    json: {
      row_id: lead.id,
      lead_key: lead.lead_key,
      text: lines.join('\n'),
      silent: true,
      button_text: 'Open posting',
      button_url: lead.posting_url,
    },
  };
});

// Hard rules from Job Scout config: location, pay floor, excluded titles.
// Every posting is checked on every scan, so a config change also applies to
// leads saved earlier. The first rule a lead breaks goes in filter_result
// ("location", "pay_floor" or "excluded_title"); a lead that breaks none gets
// "passed". Unknown pay or location never breaks a rule.
// The department and team fields are never used: DevRel roles often sit in Marketing.
const cfg = $('Job Scout config').first().json;
const rules = cfg.locationRules || {};
const payFloor = Number(cfg.payFloor) || 0;

// Case-insensitive match on whole words, so "Finance" doesn't match "Fintech".
function wordsRx(list) {
  const terms = (list || []).map((t) => String(t).trim()).filter(Boolean);
  if (!terms.length) return null;
  const alt = terms
    .map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+'))
    .join('|');
  return new RegExp('(?<![\\p{L}\\p{N}])(?:' + alt + ')(?![\\p{L}\\p{N}])', 'iu');
}
const has = (rx, s) => Boolean(rx && s && rx.test(s));

const US_STATES = new Set(('AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS ' +
  'MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY').split(' '));
// Only used when a location has no address country.
const NON_US_TEXT = wordsRx(['Canada', 'UK', 'United Kingdom', 'Europe', 'EMEA', 'EU', 'European Union',
  'APAC', 'LATAM', 'Latin America', 'Asia', 'India', 'Australia', 'Mexico', 'Brazil', 'Germany',
  'France', 'Spain', 'Ireland', 'Netherlands', 'Poland', 'Portugal', 'Japan', 'Singapore', 'Israel',
  'London', 'Berlin', 'Toronto']);
const REMOTE = wordsRx(['remote']);
const usNames = rules.usCountryNames || ['United States', 'USA', 'US'];
const US_TEXT = wordsRx(usNames);
const usKey = (s) => String(s).toLowerCase().replace(/\./g, '').replace(/\s+/g, ' ').trim();
const US_KEYS = new Set(usNames.map(usKey));
const metros = (rules.metros || []).map((m) => ({
  cities: wordsRx(m.cities),
  regions: wordsRx(m.regions),
  workplaceTypes: (m.workplaceTypes || []).map((w) => String(w).toLowerCase()),
}));

// "Plano, TX" -> "TX"
function stateCode(text) {
  const m = /,\s*([A-Z]{2})\b/.exec(text || '');
  return m && US_STATES.has(m[1]) ? m[1] : '';
}

function countryOf(p) {
  if (p.country) return US_KEYS.has(usKey(p.country)) ? 'us' : 'other';
  if (has(US_TEXT, p.text) || stateCode(p.text)) return 'us';
  if (has(NON_US_TEXT, p.text)) return 'other';
  return 'unknown';
}

// One location of a posting: "us_remote", "metro", "unclear" or "no".
function placeVerdict(p, workplaceType) {
  const country = countryOf(p);
  if (country === 'other') return 'no';
  const remote = workplaceType === 'remote' || has(REMOTE, p.text);
  if (remote) {
    if (rules.usRemote === false) return 'no';
    return country === 'us' ? 'us_remote' : 'unclear';
  }
  const region = p.region || stateCode(p.text);
  for (const m of metros) {
    const typeOk = !workplaceType || m.workplaceTypes.includes(workplaceType);
    const inCity = has(m.cities, p.locality) || has(m.cities, p.text);
    const regionOk = !region || has(m.regions, region);
    if (inCity && regionOk) return typeOk ? 'metro' : 'no';
  }
  // A location with no city ("Texas", "United States") might still be in a metro.
  const cityKnown = Boolean(p.locality) || /,/.test(p.text);
  const maybeMetro = metros.some((m) =>
    (!workplaceType || m.workplaceTypes.includes(workplaceType)) &&
    (!region || has(m.regions, region) || has(m.regions, p.text)));
  return !cityKnown && maybeMetro ? 'unclear' : 'no';
}

function locationBasis(places, workplaceType) {
  if (!places.length) return 'unclear';
  const verdicts = places.map((p) => placeVerdict(p, workplaceType));
  for (const v of ['us_remote', 'metro', 'unclear']) if (verdicts.includes(v)) return v;
  return '';
}

const EXCLUDED = wordsRx(cfg.excludedTitles);

return $input.all().map(({ json }) => {
  const { places, ...lead } = json;
  const basis = locationBasis(places || [], String(lead.workplace_type || '').toLowerCase());
  let result = 'passed';
  if (!basis) result = 'location';
  else if (typeof lead.pay_max === 'number' && lead.pay_max < payFloor) result = 'pay_floor';
  else if (has(EXCLUDED, lead.title)) result = 'excluded_title';
  return { json: { ...lead, location_basis: basis, filter_result: result } };
});
